-- {"query": "1770.sql", "dataset": "stackoverflow", "version": "v1.2", "prompt": "p1", "model": "gpt-4.1-mini", "temperature": 1.7, "max_tokens": 16384, "reasoning": "minimal", "input_tokens": 2027, "output_tokens": 1909} 

with TopUserBadgesWithRanks as (
    select 
	base_u.Id as UserId,
	base_u.DisplayName, 
    base_u.Reputation,
    calc_words.occurence_count,
	badge.Name as BadgeName,
	badge.Class,
	badge.TagBased,
	row_number() over (
	    partition by base_u.Id order by badge.Date desc, badge.Class asc
	) as BadgeRank
from Users base_u
left join Badges badge 
	on badge.UserId = base_u.Id
cross join lateral (
    select count(*) as occurence_count
    from (
       select unnest(string_to_array(coalesce(posts.Title,''), ' ')) word
       union all
       select unnest(string_to_array(coalesce(comment.Text,''), ' '))
       from Comments comment 
       where comment.UserId = base_u.Id limit 100
    ) words_all where words_all.word ilike 'error%'
) calc_words
where occurence_count > 0 ],
